/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isStringArray = require( '@stdlib/assert/is-string-array' ).primitives;
var isEmptyArrayLikeObject = require( '@stdlib/assert/is-empty-array-like-object' );
var isFunction = require( '@stdlib/assert/is-function' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var copy = require( '@stdlib/array/base/copy' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'plot:view:browser:middleware:plot-try-assign' );


// MAIN //

/**
* Returns a middleware function for attempting to assign the body of an HTTP request to a nested property on a plot instance.
*
* ## Notes
*
* -   A plot instance is assumed to be bound to a request's `this` context.
*
* @private
* @param {Array<string>} path - nested object property path
* @param {string} prop - nested object property name
* @param {Function} [transform] - synchronous transform function to apply to request body before assignment
* @throws {TypeError} first argument must be an array of strings
* @throws {TypeError} second argument must be a string
* @throws {TypeError} third argument must be a function
* @returns {Function} middleware function
*/
function factory( path, prop, transform ) {
	if ( !isStringArray( path ) && !isEmptyArrayLikeObject( path ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an array of strings. Value: `%s`.', path ) );
	}
	if ( !isString( prop ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a string. Value: `%s`.', prop ) );
	}
	if ( arguments.length > 2 ) {
		if ( !isFunction( transform ) ) {
			throw new TypeError( format( 'invalid argument. Third argument must be a function. Value: `%s`', transform ) );
		}
	}
	path = copy( path ); // note: copy to prevent external mutation
	return tryAssign;

	/**
	* Middleware function for attempting to assign the body of an HTTP request to a nested property on a plot instance.
	*
	* @private
	* @param {Object} request - request object
	* @param {Object} response - response object
	* @param {Callback} next - callback to invoke upon completion
	* @returns {void}
	*/
	function tryAssign( request, response, next ) {
		var value;
		var body;
		var o;
		var k;
		var i;

		body = request.body;
		debug( 'New value: %s', body );

		if ( transform ) {
			debug( 'Applying transform...' );
			try {
				value = transform( body );
			} catch ( err ) {
				debug( 'Encountered an error when attempting to transform request body. Error: %s', err.message );
				return next({
					'statusCode': 400,
					'error': 'Bad Request',
					'message': format( 'Invalid value: %s. Error: %s', body, err.message )
				});
			}
			debug( 'Successfully applied transform.' );
		} else {
			value = body;
		}
		// Resolve the nested object to assign to...
		o = this.plot;
		for ( i = 0; i < path.length; i++ ) {
			k = path[ i ];
			if ( k[ 0 ] === ':' ) {
				k = request.params[ k.substring( 1 ) ];
			}
			o = o[ k ];
			if ( o === void 0 ) {
				break;
			}
		}
		debug( 'Performing assignment...' );
		try {
			o[ prop ] = value;
		} catch ( err ) {
			debug( 'Encountered an error when attempting to assign value. Error: %s', err.message );
			return next({
				'statusCode': 400,
				'error': 'Bad Request',
				'message': format( 'Invalid value: %s. Error: %s', body, err.message )
			});
		}
		debug( 'Successfully performed assignment.' );
		next();
	}
}


// EXPORTS //

module.exports = factory;
